<script setup lang="ts">
import {displayText,ruleVersionText} from './api'
import {pollRunProgress} from './runProgress'
import { computed, onMounted, onUnmounted, ref, watch } from 'vue'
import Icon from './components/Icon.vue'
import CampusImageMap from './components/CampusImageMap.vue'
import SituationView from './components/SituationView.vue'
import MapTaskWorkbench from './components/MapTaskWorkbench.vue'
import EvidenceWorkbench from './components/EvidenceWorkbench.vue'
import TaskCenter from './components/TaskCenter.vue'
import DeviceCenter from './components/DeviceCenter.vue'
import AssessmentReportView from './components/AssessmentReportView.vue'
import {matchesAssessment,selectAssessment,validPage} from './assessmentSelection'
import type {EvidenceRun,DemoScenario} from './evidence'
import './day5.css'
import {useExecution,type ExecutionTask} from './execution'
import './day4.css'
import type { EvidenceSnapshot } from './evidence'
import './day3.css'
import {useSituation,type MapTask} from './situation'
import './day2.css'
import { api,label,time,type Incident,type Location,type Device,type KnowledgeDocument,type Resource,type Run,type RunEvent,type SystemStatus,type Conversation,type Observation } from './api'
const nav=[{id:'workbench',name:'智能工作台',icon:'home'},{id:'tasks',name:'任务中心',icon:'task'},{id:'risk',name:'风险研判',icon:'shield'},{id:'flow',name:'智能体编排',icon:'flow'},{id:'map',name:'全域态势',icon:'map'},{id:'devices',name:'设备中心',icon:'device'},{id:'knowledge',name:'知识中心',icon:'book'},{id:'training',name:'智能实训',icon:'training'},{id:'settings',name:'系统管理',icon:'settings'}]
const page=ref(validPage(localStorage.getItem('tq-page'),nav.map(item=>item.id))), sideOpen=ref(window.innerWidth>1080), loading=ref(true), error=ref(''), busy=ref(false), instruction=ref(''), tab=ref('overview'), selectedLocation=ref(''), query=ref(''), taskFilter=ref('all'), activeDevice=ref<Device|null>(null), deviceObservations=ref<Observation[]>([]), selectedDoc=ref<KnowledgeDocument|null>(null)
const incidents=ref<Incident[]>([]), incident=ref<Incident|null>(null), locations=ref<Location[]>([]), devices=ref<Device[]>([]), knowledge=ref<KnowledgeDocument[]>([]), resources=ref<Resource[]>([]), runs=ref<Run[]>([]), currentRun=ref<Run|null>(null), events=ref<RunEvent[]>([]), conversations=ref<Conversation[]>([]), conversationId=ref(''), system=ref<SystemStatus|null>(null)
const evidenceSnapshot=ref<EvidenceSnapshot|null>(null)
const selectedEvidenceRun=ref<EvidenceRun|null>(null),scenarioBusy=ref(false),scenarioError=ref('')
let deviceRequestGeneration=0,contextGeneration=0
const deviceLoading=ref(false)
const contextLoading=ref(false)
function acceptEvidenceRun(value:EvidenceRun|null){if(!value){selectedEvidenceRun.value=null;return}if(evidenceSnapshot.value&&matchesAssessment(evidenceSnapshot.value,value)){selectedEvidenceRun.value=value;const index=runs.value.findIndex(item=>item.id===value.id);if(index>=0)runs.value[index]=value;else runs.value.unshift(value)}}
function updateRiskRun(value:Run){if(evidenceSnapshot.value)acceptEvidenceRun(value as EvidenceRun);else if(currentRun.value?.id===value.id){currentRun.value=value;const index=runs.value.findIndex(item=>item.id===value.id);if(index>=0)runs.value[index]=value}}
async function prepareDemo(){if(scenarioBusy.value)return;const token=++openRunGeneration;scenarioBusy.value=true;scenarioError.value='';try{const scenario=await api<DemoScenario>('/demo-scenarios/evt-008/prepare',{});await situation.refresh(true);incidents.value=await api<Incident[]>('/incidents');if(token!==openRunGeneration)return;execution.select(scenario.root_task_id||'');returnSelection.value=null;situation.view.value='map';situation.choose({kind:'building',id:scenario.building_id});navigate('map')}catch(e){if(token===openRunGeneration)scenarioError.value=(e as Error).message}finally{scenarioBusy.value=false}}
function openExecutionId(id:string){const task=execution.tasks.value.find(item=>item.id===id);if(task)openExecution(task);else error.value='关联执行任务暂未加载，请刷新任务中心后重试。'}
async function openRiskRun(value:Run){await openRun(value,true,()=>true,'risk')}
const evidenceViewVersion=ref(0)
let openRunGeneration=0
const situation=useSituation(), mapTask=ref<MapTask|null>(null), returnSelection=ref<MapTask|null>(null)
const execution=useExecution(),executionTasks=execution.tasks,executionSelected=execution.selected,executionResources=execution.resources
function openExecution(task:ExecutionTask){execution.upsert(task);execution.select(task.id);navigate('tasks')}
async function showExecutionMap(task:ExecutionTask){const token=++openRunGeneration;execution.upsert(task);execution.select(task.id);await situation.refresh(true);if(token!==openRunGeneration||execution.selectedId.value!==task.id)return;returnSelection.value=null;situation.view.value='coordination';situation.choose({kind:'building',id:task.target_building_id});if(task.image_id)situation.imageId.value=task.image_id;situation.layers.value.routes=true;situation.layers.value.drone=true;situation.layers.value.robot=true;navigate('map')}
async function showExecutionObject(kind:'incident'|'device',id:string){const token=++openRunGeneration,taskId=execution.selectedId.value;await situation.refresh(true);if(token!==openRunGeneration||execution.selectedId.value!==taskId)return;returnSelection.value=null;situation.view.value='map';situation.choose({kind,id});navigate('map')}
async function openExecutionRun(id:string){const token=++openRunGeneration,taskId=execution.selectedId.value;try{const selectedRun=await api<Run>(`/runs/${encodeURIComponent(id)}`);if(token!==openRunGeneration||execution.selectedId.value!==taskId)return;await openRun(selectedRun,true,()=>execution.selectedId.value===taskId)}catch(e){if(token===openRunGeneration&&execution.selectedId.value===taskId)error.value=(e as Error).message}}
const mapData=situation.data, mapImage=situation.image, mapLayers=situation.layers, mapFocus=situation.focus, mapSelected=situation.selection, mapPatrol=situation.patrol
watch(page,value=>localStorage.setItem('tq-page',value))
function dismissEvidence(){openRunGeneration++;evidenceSnapshot.value=null;selectedEvidenceRun.value=null;localStorage.removeItem('tq-evidence-snapshot')}
function openEvidence(snapshot:EvidenceSnapshot){dismissMapTask();returnSelection.value=null;evidenceSnapshot.value=snapshot;selectedEvidenceRun.value=selectAssessment(snapshot,runs.value,localStorage.getItem(`tq-evidence-run:${snapshot.snapshot_id}`)) as EvidenceRun|null;evidenceViewVersion.value++;localStorage.setItem('tq-evidence-snapshot',snapshot.snapshot_id);navigate('workbench')}
function returnEvidenceToMap(){const source=evidenceSnapshot.value?.source_context;if(!source)return;returnSelection.value=null;situation.view.value=source.source_view;if(source.image_id)situation.imageId.value=source.image_id;situation.choose(source.selection);navigate('map')}
async function refreshEvidenceRuns(){try{runs.value=await api<Run[]>('/runs');await situation.refresh(true)}catch(e){error.value=(e as Error).message}}
function dismissMapTask(){mapTask.value=null;localStorage.removeItem('tq-map-task')}
function openMapTask(task:MapTask){dismissEvidence();mapTask.value=task;localStorage.setItem('tq-map-task',task.id);navigate('workbench')}
function returnToMap(){returnSelection.value=mapTask.value;if(mapTask.value)situation.restoreTask(mapTask.value);navigate('map')}
let stream:{close:()=>void}|null=null, progressGeneration=0
const prompt='检查实训楼二层异常情况，分析风险并核查关联设备与历史事件。'
const running=computed(()=>['queued','running'].includes(currentRun.value?.status||''))
const result=computed(()=>currentRun.value?.result)
const activePage=computed(()=>nav.find(n=>n.id===page.value)||nav[0]!)
const showBaseProcess=computed(()=>page.value==='workbench'&&!mapTask.value&&!evidenceSnapshot.value)
const alarmDevices=computed(()=>devices.value.filter(d=>['alarm','alert','warning'].includes(d.status)))
const filteredDevices=computed(()=>devices.value.filter(d=>`${d.name}${d.location_name}${label(d.status)}`.toLowerCase().includes(query.value.toLowerCase())))
const filteredKnowledge=computed(()=>knowledge.value.filter(d=>`${d.title}${d.content}${d.tags.join('')}`.includes(query.value)))
const filteredRuns=computed(()=>runs.value.filter(r=>(taskFilter.value==='all'||r.status===taskFilter.value)&&`${r.instruction}${r.id}`.includes(query.value)))
const toolEvents=computed(()=>events.value.filter(e=>e.tool_name&&e.type==='tool_result'))
const currentPlace=computed(()=>locations.value.find(l=>l.id===selectedLocation.value))
const phaseNames=['接收任务','监测数据','关联设备','历史事件','规则初评']
const phaseIndex=computed(()=>{if(currentRun.value?.status==='completed')return 5;if(!currentRun.value)return -1;return Math.min(4,toolEvents.value.length+1)})
const riskLabel=computed(()=>result.value?label(result.value.level):incident.value?.risk_level==='unassessed'?'待研判':label(incident.value?.risk_level))
function navigate(id:string){openRunGeneration++;deviceRequestGeneration++;contextGeneration++;page.value=nav.some(n=>n.id===id)?id:'workbench';query.value='';activeDevice.value=null;deviceObservations.value=[];deviceLoading.value=false;contextLoading.value=false;selectedDoc.value=null}
async function loadContext(id:string){const token=++contextGeneration;contextLoading.value=true;try{const [nextIncident,nextDevices]=await Promise.all([api<Incident>(`/incidents/${encodeURIComponent(id)}`),api<Device[]>(`/devices?incident_id=${encodeURIComponent(id)}`)]);if(token!==contextGeneration)return;incident.value=nextIncident;devices.value=nextDevices;selectedLocation.value=nextIncident.location_id;localStorage.setItem('tq-incident',id)}catch(e){if(token===contextGeneration)throw e}finally{if(token===contextGeneration)contextLoading.value=false}}
async function reload(){error.value='';loading.value=true;try{const data=await Promise.all([api<Incident[]>('/incidents'),api<Location[]>('/locations'),api<KnowledgeDocument[]>('/knowledge/search'),api<Resource[]>('/resources'),api<Run[]>('/runs'),api<Conversation[]>('/conversations'),api<SystemStatus>('/system/status')]);[incidents.value,locations.value,knowledge.value,resources.value,runs.value,conversations.value,system.value]=data;const id=localStorage.getItem('tq-incident');const found=incidents.value.find(i=>i.id===id)||incidents.value[0];if(found)await loadContext(found.id);const saved=localStorage.getItem('tq-run');const run=runs.value.find(r=>r.id===saved&&r.incident_id===found?.id);if(run)await openRun(run,false);await situation.refresh();const savedMapTask=localStorage.getItem('tq-map-task');if(savedMapTask){try{mapTask.value=await api<MapTask>(`/situation/tasks/${savedMapTask}`)}catch{dismissMapTask()}}const savedSnapshot=localStorage.getItem('tq-evidence-snapshot');if(savedSnapshot){try{evidenceSnapshot.value=await api<EvidenceSnapshot>(`/evidence-snapshots/${encodeURIComponent(savedSnapshot)}`);selectedEvidenceRun.value=selectAssessment(evidenceSnapshot.value,runs.value,localStorage.getItem(`tq-evidence-run:${savedSnapshot}`)) as EvidenceRun|null}catch(e){dismissEvidence();error.value=`证据快照恢复失败：${(e as Error).message}`}}}catch(e){error.value=(e as Error).message}finally{loading.value=false}}
async function newConversation(){if(running.value)return;dismissEvidence();dismissMapTask();try{const c=await api<Conversation>('/conversations',{title:'校园安全核查'});conversationId.value=c.id;conversations.value.unshift(c);currentRun.value=null;events.value=[];stream?.close();localStorage.removeItem('tq-run');navigate('workbench');instruction.value=''}catch(e){error.value=(e as Error).message}}
async function newScenario(){if(busy.value||running.value)return;busy.value=true;try{const i=await api<Incident>('/scenarios/fire/trigger',{});incidents.value.unshift(i);await loadContext(i.id);await newConversation()}catch(e){error.value=(e as Error).message}finally{busy.value=false}}
function subscribe(run:Run){stream?.close();events.value=[];const token=++progressGeneration
 if(import.meta.env.VITE_PROGRESS_TRANSPORT==='poll'){
  stream=pollRunProgress(run.id,{onNotice:message=>{if(token===progressGeneration&&currentRun.value?.id===run.id)error.value=message},onUpdate:async(batch,latest)=>{
   if(token!==progressGeneration||currentRun.value?.id!==run.id)return
   for(const event of batch)if(!events.value.some(item=>item.sequence===event.sequence))events.value.push(event)
   currentRun.value=latest
   if(batch.some(event=>event.type==='terminal')){
    const all=await api<Run[]>('/runs')
    if(token!==progressGeneration||currentRun.value?.id!==run.id)return
    runs.value=all
    if(incident.value?.id===latest.incident_id){const fresh=await api<Incident>(`/incidents/${latest.incident_id}`);if(token!==progressGeneration||currentRun.value?.id!==run.id||incident.value?.id!==fresh.id)return;incident.value=fresh;const index=incidents.value.findIndex(i=>i.id===fresh.id);if(index>=0)incidents.value[index]=fresh}
   }
  }})
  return
 }
 const active=new EventSource(`/api/v1/runs/${run.id}/events`);stream=active;active.addEventListener('update',async raw=>{if(currentRun.value?.id!==run.id)return;const event=JSON.parse((raw as MessageEvent).data) as RunEvent;if(!events.value.some(e=>e.sequence===event.sequence))events.value.push(event);try{const latest=await api<Run>(`/runs/${run.id}`);if(currentRun.value?.id!==run.id)return;currentRun.value=latest;if(!['queued','running'].includes(latest.status)){if(event.type==='terminal'){stream?.close()}runs.value=await api<Run[]>('/runs');if(incident.value?.id===latest.incident_id){const fresh=await api<Incident>(`/incidents/${latest.incident_id}`);incident.value=fresh;const index=incidents.value.findIndex(i=>i.id===fresh.id);if(index>=0)incidents.value[index]=fresh}}}catch(e){error.value=(e as Error).message}});active.onerror=()=>{if(currentRun.value&&!['queued','running'].includes(currentRun.value.status))stream?.close()}}
async function openRun(value:Run,go=true,contextStillCurrent:()=>boolean=()=>true,destination:'workbench'|'risk'='workbench'){
 if(go&&!value.evidence_snapshot_id){if(running.value&&currentRun.value?.id!==value.id){error.value='请先等待当前核查完成或停止，再切换任务。';return}dismissEvidence();dismissMapTask()}
 const token=++openRunGeneration
 try{
  if(go&&value.evidence_snapshot_id){
   const snapshot=await api<EvidenceSnapshot>(`/evidence-snapshots/${encodeURIComponent(value.evidence_snapshot_id)}`)
   if(token!==openRunGeneration||!contextStillCurrent())return
   if(!matchesAssessment(snapshot,value))throw new Error('所选核查记录与证据事件不一致，请重新读取记录。')
   const index=runs.value.findIndex(item=>item.id===value.id);if(index<0)runs.value.unshift(value);else runs.value[index]=value
   localStorage.setItem(`tq-evidence-run:${snapshot.snapshot_id}`,value.id);openEvidence(snapshot);if(destination==='risk')navigate('risk');return
  }
  const freshRun=await api<Run>(`/runs/${encodeURIComponent(value.id)}`)
  if(token!==openRunGeneration||!contextStillCurrent())return
  const [freshIncident,freshDevices]=await Promise.all([api<Incident>(`/incidents/${encodeURIComponent(freshRun.incident_id)}`),api<Device[]>(`/devices?incident_id=${encodeURIComponent(freshRun.incident_id)}`)])
  if(token!==openRunGeneration||!contextStillCurrent())return
  currentRun.value=freshRun;incident.value=freshIncident;devices.value=freshDevices;selectedLocation.value=freshIncident.location_id;conversationId.value=freshRun.conversation_id
  localStorage.setItem('tq-incident',freshIncident.id);localStorage.setItem('tq-run',freshRun.id);subscribe(freshRun);if(go)navigate(destination)
 }catch(e){if(token===openRunGeneration&&contextStillCurrent())error.value=(e as Error).message}
}
async function submit(text?:string){if(running.value||busy.value||contextLoading.value)return;const input=(text||instruction.value).trim();if(!input||!incident.value)return;error.value='';busy.value=true;try{if(!conversationId.value){const c=await api<Conversation>('/conversations',{title:'校园安全核查'});conversationId.value=c.id;conversations.value.unshift(c)}const r=await api<Run>('/runs',{conversation_id:conversationId.value,incident_id:incident.value.id,instruction:input});currentRun.value=r;runs.value.unshift(r);instruction.value='';localStorage.setItem('tq-run',r.id);subscribe(r)}catch(e){error.value=(e as Error).message}finally{busy.value=false}}
async function cancel(){if(!currentRun.value)return;try{currentRun.value=await api<Run>(`/runs/${currentRun.value.id}/cancel`,{});stream?.close();runs.value=await api<Run[]>('/runs')}catch(e){error.value=(e as Error).message}}
async function inspectDevice(device:Device){const token=++deviceRequestGeneration;activeDevice.value=device;deviceObservations.value=[];deviceLoading.value=true;try{const observations=await api<Observation[]>(`/devices/${device.id}/observations?incident_id=${incident.value?.id||''}`);if(token===deviceRequestGeneration&&activeDevice.value?.id===device.id)deviceObservations.value=observations}catch(e){if(token===deviceRequestGeneration)error.value=(e as Error).message}finally{if(token===deviceRequestGeneration)deviceLoading.value=false}}
function selectLocation(id:string){selectedLocation.value=id}
function textValue(value:unknown){return typeof value==='object'?JSON.stringify(value):String(value??'—')}
function prettyTool(name:string|null){return({query_sensor_data:'监测数据查询',query_device_status:'关联设备查询',query_event_history:'历史事件检索'} as Record<string,string>)[name||'']||name||'业务步骤'}
function stageStatus(index:number){return index<phaseIndex.value?'done':index===phaseIndex.value&&running.value?'active':'waiting'}
function downloadResult(){if(!currentRun.value?.result)return;const blob=new Blob([JSON.stringify({scope:'Day 1 规则初评记录，非最终事件报告',incident:incident.value,run:currentRun.value,events:events.value},null,2)],{type:'application/json;charset=utf-8'});const a=document.createElement('a');a.href=URL.createObjectURL(blob);a.download=`初评记录-${currentRun.value.id}.json`;a.click();URL.revokeObjectURL(a.href)}
function selectIncident(event:Event){if(running.value||busy.value)return;openRunGeneration++;const id=(event.target as HTMLSelectElement).value;stream?.close();currentRun.value=null;events.value=[];conversationId.value='';localStorage.removeItem('tq-run');loadContext(id).catch(e=>error.value=e.message)}
async function fullScreen(){try{if(document.fullscreenElement)await document.exitFullscreen();else await document.documentElement.requestFullscreen()}catch{error.value='当前窗口不支持整页全屏，可使用地图内的全屏按钮。'}}
onMounted(()=>{void reload();execution.start()});onUnmounted(()=>{progressGeneration++;stream?.close();execution.stop()})
</script>

<template>
 <div class="app-shell">
  <header class="topbar">
   <a class="brand" href="#" @click.prevent="navigate('workbench')"><span class="brand-symbol"><svg viewBox="0 0 48 48"><path d="m24 6 16 25-16 11L8 31 24 6Z"/><path d="M4 29c5-11 34-18 40-13M9 37c11 2 29-6 33-14"/></svg></span><span><strong>天亨<span class="brand-separator"> / </span><span class="brand-sub">智能安全协同平台</span></strong><small>SKY · AIR · GROUND · PEOPLE</small></span></a>
   <div class="topbar-right"><span class="connection" :class="{offline:!!error}"><i></i>{{error?'连接需检查':'本地服务已连接'}}</span><span class="topbar-divider"></span><span class="mode-chip"><Icon name="shield" :size="14"/>演示环境</span><button class="icon-button" title="刷新数据" aria-label="刷新数据" @click="reload"><Icon name="refresh" :size="17"/></button><button class="icon-button" title="全屏" aria-label="全屏" @click="fullScreen"><Icon name="expand" :size="18"/></button></div>
  </header>
  <aside class="sidebar">
   <button class="new-task" @click="newConversation" :disabled="running"><Icon name="plus" :size="18"/>新建任务 <span>＋</span></button>
   <div class="nav-label">工作空间</div>
   <nav><button v-for="item in nav" :key="item.id" :aria-label="item.name" :class="['nav-item',{selected:page===item.id}]" @click="navigate(item.id)"><Icon :name="item.icon" :size="19"/><span>{{displayText(item.name)}}</span><span v-if="item.id==='tasks'&&executionTasks.length" class="nav-count">{{executionTasks.length}}</span><span v-if="item.id==='workbench'" class="nav-active-dot"></span></button></nav>
   <div class="sidebar-history"><div class="nav-label">最近核查 <span>{{runs.length}}</span></div><button v-for="run in runs.slice(0,3)" :key="run.id" class="history-item" @click="openRun(run)"><span class="history-dot" :class="run.status"></span><span>{{displayText(run.instruction)}}</span></button><p v-if="!runs.length" class="muted small">执行首个任务后显示记录</p></div>
   <div class="sidebar-bottom"><div class="workspace-card"><span class="campus-mini"><Icon name="map" :size="24"/></span><div><strong>{{displayText(locations.find(l=>l.kind==='campus')?.name||'演示校园')}}</strong><small>本地演示工作空间</small></div><span class="tiny-dot"></span></div><div class="user-line"><span class="avatar"><Icon name="user" :size="17"/></span><span>演示管理员<small>LOCAL WORKSPACE</small></span><span class="version">v0.1</span></div></div>
  </aside>
  <main class="main-area" :class="{'without-panel':!sideOpen||!showBaseProcess,'situation-mode':page==='map'}">
   <div v-if="error" class="error-banner" role="alert"><Icon name="info" :size="17"/><span>{{displayText(error)}}</span><button @click="error=''" aria-label="关闭错误"><Icon name="close" :size="16"/></button></div>
   <div class="page-heading"><div class="heading-title"><span class="breadcrumb">工作空间 <Icon name="chevron" :size="12"/></span><h1>{{displayText(activePage.name)}}</h1></div><div class="heading-actions"><span class="day-badge">{{page==='tasks'?'DAY 04':page==='workbench'&&evidenceSnapshot?'DAY 03':page==='map'||mapTask?'DAY 02':'DAY 01'}} <span>{{page==='tasks'?'协同执行':page==='workbench'&&evidenceSnapshot?'证据核查':page==='map'||mapTask?'空间协同':'基础能力'}}</span></span><button v-if="showBaseProcess" class="icon-button panel-toggle" :aria-label="sideOpen?'收起执行面板':'展开执行面板'" @click="sideOpen=!sideOpen"><Icon name="collapse" :size="18"/></button></div></div>
   <div v-if="loading" class="loading-state"><span class="spinner"></span>正在连接本地工作空间…</div>
   <div v-else class="work-area">
    <section class="primary-column">
     <template v-if="page==='workbench'&&evidenceSnapshot"><EvidenceWorkbench :key="`${evidenceSnapshot.snapshot_id}:${evidenceViewVersion}`" :snapshot="evidenceSnapshot" :preparing-demo="scenarioBusy" :demo-error="scenarioError" @prepare-demo="prepareDemo" @return-map="returnEvidenceToMap" @dismiss="dismissEvidence" @run-changed="refreshEvidenceRuns" @run-selected="acceptEvidenceRun" @show-report="navigate('risk')" @open-execution="openExecution"/></template>
     <template v-else-if="page==='workbench'&&mapTask"><MapTaskWorkbench :task="mapTask" @return-map="returnToMap" @dismiss="dismissMapTask"/></template>
     <template v-else-if="page==='workbench'">
      <div class="demo-chain-entry"><div><strong>EVT-008 · 温度异常演示链路</strong><p>明确准备后定位实训基地，选择 TEMP-008 开始核查；不会自动启动巡检。</p></div><button class="outline-button" :disabled="scenarioBusy" @click="prepareDemo">{{scenarioBusy?'正在准备…':'准备 EVT-008 演示链路'}}</button><p v-if="scenarioError" class="evidence-error" role="alert">{{displayText(scenarioError)}}</p></div>
      <div class="workspace-tabs"><button :class="{active:tab==='overview'}" @click="tab='overview'"><Icon name="spark" :size="16"/>任务工作台</button><button :class="{active:tab==='map'}" @click="tab='map'"><Icon name="map" :size="16"/>态势地图</button><button :class="{active:tab==='evidence'}" @click="tab='evidence'"><Icon name="link" :size="16"/>关联证据 <span>{{result?.evidence.length||0}}</span></button><span class="tabs-fill"></span><span class="small muted">模拟数据 · 真实工具执行</span></div>
      <div class="workspace-body">
       <p v-if="contextLoading" class="panel-hint" role="status">正在读取所选事件，完成后可提交核查。</p><div class="scene-strip"><span class="incident-symbol"><Icon name="risk" :size="20"/></span><div><div class="scene-title">{{displayText(incident?.title||'尚无事件')}}<span class="subtle-tag">模拟告警</span></div><p>{{displayText(incident?.location_name)}}<span>·</span>{{time(incident?.triggered_at,true)}}</p></div><select aria-label="选择演示事件" :value="incident?.id" @change="selectIncident" :disabled="running||busy"><option v-for="i in incidents" :key="i.id" :value="i.id">{{displayText(i.title)}} · {{time(i.triggered_at)}}</option></select></div>
       <template v-if="tab==='overview'">
        <div v-if="!currentRun" class="welcome"><div class="agent-orb"><Icon name="spark" :size="24"/></div><div><div class="eyebrow">TIANHENG SAFETY AGENT</div><h2>让每一次处置，有据可循。</h2><p>围绕当前事件核查监测、设备与历史记录，形成可追溯的风险初评。</p></div></div>
        <div v-else class="conversation-prompt"><span class="avatar"><Icon name="user" :size="17"/></span><div>{{displayText(currentRun.instruction)}}<small>{{time(currentRun.created_at)}}</small></div></div>
        <div class="section-caption"><span><Icon name="map" :size="16"/>现场态势</span><button class="text-button" @click="navigate('map')">查看全图 <Icon name="arrow" :size="14"/></button></div>
        <div class="scene-grid"><CampusImageMap v-if="mapData&&mapImage" :image="mapImage" :spaces="mapData.spaces" :devices="mapData.devices" :incidents="mapData.incidents" :layers="mapLayers" :selected="mapSelected" :patrol="mapPatrol" :execution-mission="executionSelected" :execution-resources="executionResources" :focus="mapFocus" @select="situation.choose"/><div class="scene-info"><div class="eyebrow">EVENT OVERVIEW</div><h3>{{displayText(incident?.location_name)}}</h3><span class="risk-pill" :class="result?.level||incident?.risk_level">{{riskLabel}}</span><p>{{displayText(incident?.summary)}}</p><div class="scene-metric"><span>关联异常设备</span><strong>{{alarmDevices.length}}<small> 台</small></strong></div><div class="scene-info-bottom"><Icon name="info" :size="13"/>数据来自预置演示场景</div></div></div>
        <div v-if="currentRun" class="execution-strip"><div class="execution-title"><span><Icon name="flow" :size="16"/>基础核查流程</span><span class="status-badge" :class="currentRun.status">{{label(currentRun.status)}}</span></div><div class="phases"><div v-for="(phase,index) in phaseNames" :key="phase" class="phase" :class="stageStatus(index)"><span class="phase-node"><Icon v-if="stageStatus(index)==='done'" name="check" :size="12"/><span v-else>{{index+1}}</span></span><span>{{phase}}</span></div></div></div>
        <div v-if="result" class="assessment"><div class="section-caption"><span><Icon name="shield" :size="17"/>规则初评结果</span><span class="subtle-tag">{{ruleVersionText(result.rule_version)}}</span></div><h3>{{displayText(result.title)}}</h3><ul class="reason-list"><li v-for="reason in result.reasons" :key="reason"><i></i>{{displayText(reason)}}</li></ul><div v-if="result.uncertainties.length" class="uncertainty"><strong>待核实信息</strong><p v-for="unknown in result.uncertainties" :key="unknown">{{displayText(unknown)}}</p></div><button class="text-button" @click="navigate('risk')">展开依据与建议 <Icon name="arrow" :size="14"/></button></div>
        <div v-else-if="!currentRun" class="suggested-task"><div><span class="eyebrow">建议开始</span><h3>实训楼异常核查</h3><p>查询监测数据、关联设备与历史事件</p></div><button class="round-button" @click="submit(prompt)" :disabled="busy||contextLoading" aria-label="开始实训楼异常核查"><Icon name="arrow" :size="21"/></button></div>
        <div v-if="currentRun?.error" class="inline-error">{{displayText(currentRun.error)}}</div>
        <div class="scope-note"><Icon name="info" :size="14"/><span>当前使用规则演示工作流。模型自主规划与方案审批仍待后续接入；模拟执行可从证据核查结果进入任务中心。</span></div>
       </template>
       <template v-else-if="tab==='map'"><CampusImageMap v-if="mapData&&mapImage" :image="mapImage" :spaces="mapData.spaces" :devices="mapData.devices" :incidents="mapData.incidents" :layers="mapLayers" :selected="mapSelected" :patrol="mapPatrol" :execution-mission="executionSelected" :execution-resources="executionResources" :focus="mapFocus" @select="situation.choose"/><div class="location-info"><h3>{{displayText(currentPlace?.name||'选择建筑')}}</h3><p class="muted">学校规划效果图作为视觉底图，设备与事件均为模拟。完整空间交互请进入全域态势。</p><div class="location-buttons"><button v-for="l in locations" :key="l.id" class="outline-button" :class="{chosen:selectedLocation===l.id}" @click="selectLocation(l.id)">{{displayText(l.name)}}</button></div></div></template>
       <template v-else><div v-if="!result" class="empty-state"><Icon name="link" :size="36"/><h3>执行核查后查看证据</h3><p>证据由实际工具查询返回，包含可追溯的来源记录。</p><button class="primary-button" @click="submit(prompt)" :disabled="busy||running||contextLoading">开始基础核查</button></div><div v-else class="evidence-list"><article v-for="(e,i) in result.evidence" :key="i" class="evidence-card"><span class="number-label">0{{i+1}}</span><div><h3>{{e.label}}</h3><p>{{textValue(e.value)}}</p><code>{{e.source_id}}</code></div></article></div></template>
      </div>
      <form class="composer" @submit.prevent="submit()"><div class="composer-input"><textarea v-model="instruction" aria-label="任务指令" placeholder="描述当前事件的核查任务，或点击上方建议开始…" rows="2" :disabled="running||contextLoading" @keydown.enter.exact.prevent="submit()"></textarea><button v-if="running" type="button" class="send-button stop" aria-label="停止执行" @click="cancel"><Icon name="stop" :size="18"/></button><button v-else type="submit" class="send-button" aria-label="发送任务" :disabled="busy||contextLoading||!instruction.trim()"><Icon name="send" :size="20"/></button></div><div class="composer-footer"><div><span><Icon name="device" :size="13"/>关联设备数据</span><span><Icon name="flow" :size="13"/>3 个真实工具</span></div><span class="mode-label"><i></i>规则演示模式</span></div></form>
     </template>

     <template v-else-if="page==='tasks'"><TaskCenter :runs="runs" :map-tasks="mapData?.tasks||[]" :incidents="incidents" @open-run="openRun" @open-run-id="openExecutionRun" @open-map-task="openMapTask" @show-map="showExecutionMap" @show-event="showExecutionObject('incident',$event)" @show-device="showExecutionObject('device',$event)" @new-analysis="newConversation"/></template>
     <template v-else-if="page==='devices'"><DeviceCenter @open-evidence="openEvidence" @show-event="showExecutionObject('incident',$event)" @show-device="showExecutionObject('device',$event)"/></template>
     <template v-else-if="page==='knowledge'"><div class="module-header"><div><h2>知识与预案</h2><p>预置演示资料，引用时保留来源与版本。</p></div><span class="count-pill" role="status">匹配 {{filteredKnowledge.length}} / 共 {{knowledge.length}} 份资料</span></div><div class="filter-bar"><div class="search-field"><Icon name="search" :size="16"/><input v-model="query" placeholder="搜索预案标题、标签或正文" aria-label="搜索知识库"/></div></div><div v-if="!filteredKnowledge.length" class="empty-state" role="status"><Icon name="search" :size="36"/><h3>{{query?'没有匹配的资料':'暂无知识资料'}}</h3><p>{{query?'请调整关键词，或清空搜索查看全部资料。':'资料加载后将在这里显示，可使用顶部刷新重试。'}}</p><button v-if="query" class="secondary-button" @click="query=''">清空搜索</button></div><button v-for="doc in filteredKnowledge" :key="doc.id" class="document-row" @click="selectedDoc=doc"><span class="document-icon"><Icon name="book" :size="24"/></span><div><h3>{{displayText(doc.title)}}</h3><p>{{doc.category}}<span>·</span>{{doc.version}}</p><div class="tags"><span v-for="tag in doc.tags" :key="tag">{{tag}}</span></div></div><Icon name="chevron" :size="17"/></button><article v-if="selectedDoc" class="detail-panel document-content"><div class="section-caption"><span>{{displayText(selectedDoc.title)}}</span><button class="icon-button" @click="selectedDoc=null" aria-label="关闭文档"><Icon name="close" :size="16"/></button></div><span class="subtle-tag">演示资料 · {{selectedDoc.version}}</span><pre>{{displayText(selectedDoc.content)}}</pre></article></template>
     <template v-else-if="page==='risk'"><AssessmentReportView :snapshot="evidenceSnapshot" :run="evidenceSnapshot?selectedEvidenceRun:currentRun" :runs="runs" @open-run="openRiskRun" @run-updated="updateRiskRun" @return-workbench="navigate('workbench')" @open-task="openExecutionId"/></template>
     <template v-else-if="page==='map'"><SituationView :initial-selection="returnSelection" @open-task="openMapTask" @open-evidence="openEvidence" @open-execution="openExecution"/></template>
     <template v-else-if="page==='flow'"><div class="module-header"><div><h2>当前工作流</h2><p>固定执行路径可追溯，所有工具均由后端实际运行。</p></div><span class="subtle-tag">只读流程</span></div><div class="flow-list"><div v-for="(node,i) in ['接收指令并校验事件','query_sensor_data · 查询监测','query_device_status · 查询设备','query_event_history · 查询历史','演示规则初评并保存结果']" :key="node" class="flow-node"><span>{{String(i+1).padStart(2,'0')}}</span><strong>{{node}}</strong><Icon name="check" :size="17"/></div></div><div class="detail-panel"><h3>后续阶段</h3><p class="muted">模型自主规划、预案检索和人工审批尚待建设；证据核查已可衔接任务中心的模拟派发。当前不提供拖拽编辑，避免修改图形后与实际执行逻辑脱节。</p><button class="outline-button" @click="navigate('workbench')">运行当前流程 <Icon name="arrow" :size="15"/></button></div></template>
     <template v-else-if="page==='training'"><div class="module-header"><div><h2>校园安全实训</h2><p>使用独立的演示场景，重复练习取证与研判流程。</p></div></div><div class="training-card"><span class="training-symbol"><Icon name="shield" :size="38"/></span><span class="subtle-tag">场景 01 · 已可用</span><h2>实训楼疑似火情</h2><p>模拟温度异常、烟雾告警与设备状态变化。创建新场景不会覆盖历史任务与证据。</p><div class="tags"><span>多源数据</span><span>基础核查</span><span>规则初评</span></div><button class="primary-button" @click="newScenario" :disabled="busy||running"><Icon name="plus" :size="16"/>{{busy?'正在创建…':'创建新的演示场景'}}</button></div><div class="scope-note"><Icon name="info" :size="14"/>当前训练不连接真实设备，不发送外部通知；评分与课程管理尚未接入。</div></template>
     <template v-else-if="page==='settings'"><div class="module-header"><div><h2>运行环境</h2><p>当前服务与能力状态。</p></div><button class="outline-button" @click="reload"><Icon name="refresh" :size="15"/>刷新</button></div><div class="settings-list"><div><span>应用版本</span><strong>{{system?.version||'0.1.0'}} · Day 5</strong></div><div><span>数据存储</span><strong>{{system?.database==='connected'?'本地数据库已连接':system?.database}}</strong></div><div><span>工作流模式</span><strong>规则演示 · 3 个实际工具</strong></div><div><span>模型服务商</span><strong>{{system?.model.provider||'智谱'}}</strong></div><div><span>模型名称</span><strong>{{system?.model.model||'尚未配置'}}</strong></div><div><span>独立模型探测</span><strong :class="system?.model.verified?'success-text':''">{{system?.model.verified?'已验证真实工具调用':'尚未验证'}}</strong></div></div><div class="detail-panel"><h3>模型状态说明</h3><p class="muted">{{displayText(system?.model.message)}}</p><p class="muted">独立模型探测成功不代表工作台已采用模型自主规划。当前核查仍执行固定的规则演示流程，任务中心支持空天地模拟执行；API Key 仅在后端配置，不在页面展示。</p></div></template>
    </section>
    <aside v-if="sideOpen&&showBaseProcess" class="process-panel">
     <div class="panel-heading"><span><Icon name="signal" :size="17"/>执行过程</span><span class="live-label"><i></i>{{running?'执行中':'实时记录'}}</span></div>
     <div class="process-body"><div class="process-overline">{{currentRun?'当前核查':'等待任务'}}<span>{{currentRun?time(currentRun.created_at):'—'}}</span></div><div v-if="!events.length" class="process-empty"><span class="process-empty-icon"><Icon name="flow" :size="24"/></span><h3>准备就绪</h3><p>提交核查任务后，这里会显示实际执行阶段与工具返回记录。</p><div class="process-ready"><i></i>本地业务工具可用</div></div><div v-else class="timeline"><details v-for="event in events" :key="event.sequence" class="timeline-event" :class="event.status"><summary><span class="timeline-dot"></span><small>{{time(event.created_at)}}</small><strong>{{displayText(event.message)}}</strong><Icon v-if="event.data" name="chevron" :size="12"/></summary><small v-if="event.data">原始接口记录（保留技术标识）</small><pre v-if="event.data">{{JSON.stringify(event.data,null,2)}}</pre><p v-else class="muted small">{{event.stage}} · {{label(event.status)}}</p></details></div></div>
     <div class="panel-section"><div class="section-caption"><span><Icon name="link" :size="15"/>工具调用</span><span class="count-number">{{toolEvents.length}}</span></div><div v-if="!toolEvents.length" class="tool-placeholder">尚未执行工具调用</div><div v-for="tool in toolEvents" :key="tool.sequence" class="tool-record"><span class="tool-check"><Icon name="check" :size="11"/></span><span>{{prettyTool(tool.tool_name)}}</span><small>{{tool.duration_ms!==null?`${tool.duration_ms} ms`:'已返回'}}</small></div></div>
     <div class="panel-section"><div class="section-caption"><span><Icon name="file" :size="15"/>本次产物</span></div><button v-if="result" class="artifact-card" @click="navigate('risk')"><span class="file-symbol"><Icon name="file" :size="24"/></span><div><strong>风险初评记录</strong><small>规则依据 · 关联证据</small></div><Icon name="chevron" :size="16"/></button><div v-else class="artifact-empty"><Icon name="file" :size="24"/><span>核查完成后生成初评记录</span></div></div>
     <div class="panel-bottom"><div><span class="tiny-dot"></span>真实函数执行</div><p>设备与位置使用模拟数据<br/>过程记录不包含模型隐藏思维</p></div>
    </aside>
   </div>
  </main>
 </div>
</template>
